#!/usr/bin/env python3
"""Private B3 compressed working-set generator (no generated bytes in Git).

Create: --rom MERGED.gba --profile PHYSICAL.json --out NEW_PRIVATE_DIR
Verify: --rom MERGED.gba --verify EXISTING_PRIVATE_DIR [--placement HEADER]

Uses the scene schema of msb/residency.py plus rom_sha256. Each page is an
independent LZ4 block, and the encoder has no external Python dependencies.
The generated C header and metadata are private build inputs, not source.
"""
import argparse
import hashlib
import json
import re
import struct
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "msb"))
from residency import ROM_BYTES, PAGE_BYTES, PAGE_COUNT, score_profiles

REGIONS = ("r1", "r3", "rt")
MAX_BYTES = {"r1": 12288, "r3": 8192, "rt": 4096}
HOT_MAX = 56
PACK_MAX = 64


def sha(data):
    return hashlib.sha256(data).hexdigest()


def extension(out, n):
    while n >= 255:
        out.append(255)
        n -= 255
    out.append(n)


def encode_page(raw):
    """Deterministic greedy LZ4 block, with a short history per four-byte key."""
    if len(raw) != PAGE_BYTES:
        raise ValueError("expected a full 4 KiB page")
    raw = bytes(raw)  # hashable history keys, including bytearray input
    out, history = bytearray(), {}
    anchor = pos = 0

    def remember(i):
        if i + 4 <= len(raw):
            chain = history.setdefault(raw[i:i+4], [])
            chain.append(i)
            if len(chain) > 24:
                del chain[0]

    # LZ4-compatible last match and last literal restrictions.
    while pos <= len(raw) - 12:
        best, where = 0, 0
        max_len = len(raw) - 5 - pos
        for old in reversed(history.get(raw[pos:pos+4], ())):
            n = 4
            while n < max_len and raw[old+n] == raw[pos+n]:
                n += 1
            if n > best:
                best, where = n, old
            if best == max_len:
                break
        if best < 4:
            remember(pos)
            pos += 1
            continue
        lit, m = pos - anchor, best - 4
        out.append((min(lit, 15) << 4) | min(m, 15))
        if lit >= 15:
            extension(out, lit - 15)
        out.extend(raw[anchor:pos])
        out.extend(struct.pack("<H", pos - where))
        if m >= 15:
            extension(out, m - 15)
        for i in range(pos, pos + best):
            remember(i)
        pos += best
        anchor = pos
    lit = len(raw) - anchor
    out.append(min(lit, 15) << 4)
    if lit >= 15:
        extension(out, lit - 15)
    out.extend(raw[anchor:])
    return bytes(out)


def decode_page(blob):
    """Independent private build-time verification of the emitted stream."""
    i, out = 0, bytearray()

    def length(n):
        nonlocal i
        if n == 15:
            while True:
                if i >= len(blob):
                    raise ValueError("truncated length")
                v = blob[i]
                i += 1
                n += v
                if v != 255:
                    break
        return n

    while i < len(blob):
        token = blob[i]
        i += 1
        lit = length(token >> 4)
        if i + lit > len(blob) or len(out) + lit > PAGE_BYTES:
            raise ValueError("literal outside page")
        out.extend(blob[i:i+lit])
        i += lit
        if i == len(blob):
            if len(out) != PAGE_BYTES:
                raise ValueError("short decoded page")
            return bytes(out)
        if i + 2 > len(blob):
            raise ValueError("truncated distance")
        distance, = struct.unpack_from("<H", blob, i)
        i += 2
        n = length(token & 15) + 4
        if not 0 < distance <= len(out) or len(out) + n > PAGE_BYTES:
            raise ValueError("match outside page")
        for _ in range(n):
            out.append(out[-distance])
    raise ValueError("missing final literals")


def validate_sizes(sizes):
    if not isinstance(sizes, dict) or set(sizes) != set(REGIONS):
        raise ValueError("cache region sizes must name r1, r3 and rt")
    if any(type(sizes[r]) is not int or not 0 <= sizes[r] <= MAX_BYTES[r] for r in REGIONS):
        raise ValueError("cache region exceeds its configured safety limit")
    return sizes


def plan_cache(rom, scores, budgets, hot_limit):
    validate_sizes(budgets)
    if len(rom) != ROM_BYTES or not 0 <= hot_limit <= HOT_MAX:
        raise ValueError("invalid merged ROM or preferred-page budget")
    compressed = {}
    for pg in scores:
        if type(pg) is not int or not 0 <= pg < PAGE_COUNT:
            raise ValueError("page outside merged ROM")
        raw = rom[pg*PAGE_BYTES:(pg+1)*PAGE_BYTES]
        blob = encode_page(raw)
        if len(blob) < PAGE_BYTES:
            if decode_page(blob) != raw:
                raise ValueError("cache encoder round trip mismatch")
            compressed[pg] = blob
    banks = {r: bytearray() for r in REGIONS}
    entries = []
    for pg in sorted(compressed, key=lambda p: (-scores[p] / (len(compressed[p])+8), p)):
        if len(entries) == PACK_MAX:
            break
        blob = compressed[pg]
        for region in REGIONS:
            buf = banks[region]
            if len(buf) + len(blob) <= budgets[region]:
                entries.append((pg, region, len(buf), len(blob)))
                buf.extend(blob)
                break
    entries.sort()
    packed = {e[0] for e in entries}
    hot = sorted((p for p in scores if p not in packed),
                 key=lambda p: (-scores[p], p))[:hot_limit]
    return banks, entries, sorted(hot)


def render_header(banks, entries, hot):
    def array(name, data, section=""):
        attr = (' __attribute__((section("%s"), aligned(4)))' % section) if section else ""
        rows = ["    " + ",".join(str(x) for x in data[i:i+24]) + ","
                for i in range(0, len(data), 24)]
        return "static const u8 %s[%d]%s = {\n%s\n};\n" % (
            name, len(data), attr, "\n".join(rows))
    lines = ["/* Private generated B3 cache: never commit. */\n",
             "#define B3_CACHE_COUNT %du\n" % len(entries),
             "#define B3_CACHE_HOT_COUNT %du\n" % len(hot)]
    for region in REGIONS:
        if banks[region]:
            lines.append(array("b3_bank_"+region, banks[region], ".sfncache."+region))
    mask = bytearray(PAGE_COUNT//8)
    for pg in hot:
        mask[pg>>3] |= 1 << (pg&7)
    lines.append(array("b3_preferred", mask))
    lines.append("static const B3CachePage b3_cache_pages[%d] = {\n" % max(1, len(entries)))
    for pg, region, offset, size in entries:
        lines.append("    {%d,%d,b3_bank_%s+%d},\n" % (pg,size,region,offset))
    if not entries:
        lines.append("    {0,0,0},\n")
    lines.append("};\n")
    return "".join(lines).encode("ascii")


def load_meta(directory, rom=None, placement=None):
    directory = Path(directory)
    meta = json.loads((directory/"cache_meta.json").read_text())
    if meta.get("schema") != 1 or meta.get("rom_bytes") != ROM_BYTES:
        raise ValueError("unsupported private B3 cache bundle")
    sizes = validate_sizes(meta.get("region_bytes"))
    if (type(meta.get("pages")) is not int or not 0 <= meta["pages"] <= PACK_MAX
            or type(meta.get("hot")) is not int or not 0 <= meta["hot"] <= HOT_MAX):
        raise ValueError("invalid cache entry counts")
    if not re.fullmatch(r"[0-9a-f]{64}", str(meta.get("rom_sha256", ""))):
        raise ValueError("missing ROM digest")
    if sha((directory/"b3_cache_data.h").read_bytes()) != meta.get("header_sha256"):
        raise ValueError("private cache header digest mismatch")
    if rom is not None and (len(rom) != ROM_BYTES or sha(rom) != meta["rom_sha256"]):
        raise ValueError("private cache was generated from another ROM")
    if placement is not None:
        text = Path(placement).read_text()
        for region in REGIONS:
            m = re.search(r"^#define SF_NAT_CACHE_"+region.upper()+r" (\d+)u$", text, re.M)
            if not m or int(m.group(1)) != sizes[region]:
                raise ValueError("native placement was not sized for this cache: "+region)
    return meta


def main(argv=None):
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--rom", type=Path, required=True)
    ap.add_argument("--profile", type=Path)
    ap.add_argument("--out", type=Path)
    ap.add_argument("--verify", type=Path)
    ap.add_argument("--placement", type=Path)
    ap.add_argument("--r1-bytes", type=int, default=8192)
    ap.add_argument("--r3-bytes", type=int, default=6144)
    ap.add_argument("--rt-bytes", type=int, default=2048)
    ap.add_argument("--hot", type=int, default=56)
    args = ap.parse_args(argv)
    try:
        rom = args.rom.read_bytes()
        if args.verify:
            if args.out or args.profile:
                raise ValueError("choose generation or verification, not both")
            load_meta(args.verify, rom, args.placement)
            print("B3 cache: ROM/header digest and placement verified")
            return 0
        if not args.profile or not args.out or args.placement:
            raise ValueError("generation needs --profile and --out")
        here = Path(__file__).resolve().parents[1]
        root = here.parent if here.name == "ps1" else here
        if args.out.resolve().is_relative_to(root):
            raise ValueError("write generated cache outside the source tree")
        document = json.loads(args.profile.read_text())
        if document.get("rom_sha256") != sha(rom):
            raise ValueError("profile does not identify this exact private ROM")
        scores = score_profiles(document)
        banks, entries, hot = plan_cache(rom, scores, dict(r1=args.r1_bytes,
                             r3=args.r3_bytes, rt=args.rt_bytes), args.hot)
        header = render_header(banks, entries, hot)
        meta = dict(schema=1, rom_bytes=ROM_BYTES, rom_sha256=sha(rom),
                    header_sha256=sha(header), region_bytes={r: len(banks[r]) for r in REGIONS},
                    pages=len(entries), hot=len(hot))
        args.out.mkdir(parents=True, exist_ok=False)
        (args.out/"b3_cache_data.h").write_bytes(header)
        (args.out/"cache_meta.json").write_text(json.dumps(meta, indent=2, sort_keys=True)+"\n")
        load_meta(args.out, rom)
        print("B3 cache: %d packed pages, %d preferred; payload %d bytes" %
              (len(entries), len(hot), sum(meta["region_bytes"].values())))
        return 0
    except (OSError, ValueError) as exc:
        ap.error(str(exc))


if __name__ == "__main__":
    raise SystemExit(main())
